python3 - <<'EOF'
p='src/pickList.ts'
s=open(p).read()
i=s.index('export function buildPickList')
s=s[:i]+r'''interface OrderItem {
  sku: string;
  qty: number;
}

interface Order {
  id: string;
  priority: boolean;
  items: OrderItem[];
}

const ORDER_LINE = /^ORDER +([A-Za-z0-9-]+)(?: +!)?$/;
const ITEM_LINE = /^([A-Z0-9-]+) +x([1-9][0-9]*)$/;

function parseOrders(ordersText: string): Order[] {
  const orders: Order[] = [];
  const seenIds = new Set<string>();
  const problems: { line: number; description: string }[] = [];
  let current: { order: Order; line: number } | null = null;

  const closeCurrent = () => {
    if (current && current.order.items.length === 0) {
      problems.push({ line: current.line, description: `order ${current.order.id} has no items` });
    }
  };

  ordersText.split(/\r?\n/).forEach((raw, index) => {
    const lineNo = index + 1;
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) return;

    const orderMatch = ORDER_LINE.exec(line);
    if (orderMatch) {
      closeCurrent();
      const id = orderMatch[1];
      const order: Order = { id, priority: line.endsWith("!"), items: [] };
      if (seenIds.has(id)) {
        problems.push({ line: lineNo, description: `duplicate order id ${id}` });
      } else {
        seenIds.add(id);
        orders.push(order);
      }
      current = { order, line: lineNo };
      return;
    }

    const itemMatch = ITEM_LINE.exec(line);
    if (itemMatch) {
      if (!current) {
        problems.push({ line: lineNo, description: "item line before first ORDER" });
        return;
      }
      const sku = itemMatch[1];
      const qty = Number(itemMatch[2]);
      const existing = current.order.items.find((item) => item.sku === sku);
      if (existing) existing.qty += qty;
      else current.order.items.push({ sku, qty });
      return;
    }

    problems.push({ line: lineNo, description: `unrecognized line "${line}"` });
  });
  closeCurrent();

  if (problems.length > 0) {
    const first = problems.reduce((a, b) => (b.line < a.line ? b : a));
    throw new OrderFormatError(first.line, first.description);
  }
  return orders;
}

function compareLots(a: StockLot, b: StockLot): number {
  if (a.expires !== b.expires) {
    if (a.expires === null) return 1;
    if (b.expires === null) return -1;
    return a.expires < b.expires ? -1 : 1;
  }
  return a.bin < b.bin ? -1 : a.bin > b.bin ? 1 : 0;
}

function parseBin(bin: string): { aisle: string; rack: number; level: number } {
  const [aisle = "", rack = "", level = ""] = bin.split("-");
  return { aisle, rack: Number(rack), level: Number(level) };
}

function walkOrder(picks: Pick[]): Pick[] {
  const parsed = picks.map((pick, index) => ({ pick, index, ...parseBin(pick.bin) }));
  const aisles = [...new Set(parsed.map((p) => p.aisle))].sort();
  const aisleRank = new Map(aisles.map((aisle, i) => [aisle, i]));
  parsed.sort((a, b) => {
    const ra = aisleRank.get(a.aisle)!;
    const rb = aisleRank.get(b.aisle)!;
    if (ra !== rb) return ra - rb;
    if (a.rack !== b.rack) return ra % 2 === 0 ? a.rack - b.rack : b.rack - a.rack;
    if (a.level !== b.level) return a.level - b.level;
    return a.index - b.index;
  });
  return parsed.map((p) => p.pick);
}

export function buildPickList(ordersText: string, stock: StockLot[]): PickList {
  const orders = parseOrders(ordersText);
  const served = [...orders.filter((o) => o.priority), ...orders.filter((o) => !o.priority)];

  const lotsBySku = new Map<string, { lot: StockLot; left: number }[]>();
  for (const lot of stock) {
    let lots = lotsBySku.get(lot.sku);
    if (!lots) lotsBySku.set(lot.sku, (lots = []));
    lots.push({ lot, left: lot.qty });
  }
  for (const lots of lotsBySku.values()) lots.sort((a, b) => compareLots(a.lot, b.lot));

  const picks: Pick[] = [];
  const shortages: Shortage[] = [];
  for (const order of served) {
    for (const item of order.items) {
      let needed = item.qty;
      for (const entry of lotsBySku.get(item.sku) ?? []) {
        if (needed === 0) break;
        if (entry.left <= 0) continue;
        const taken = Math.min(needed, entry.left);
        entry.left -= taken;
        needed -= taken;
        picks.push({ bin: entry.lot.bin, sku: item.sku, qty: taken, orderId: order.id });
      }
      if (needed > 0) shortages.push({ orderId: order.id, sku: item.sku, missing: needed });
    }
  }

  return { picks: walkOrder(picks), shortages };
}
'''
open(p,'w').write(s)
EOF

cat >> src/pickList.test.ts <<'EOF'

import { buildPickList, type StockLot } from "./pickList";

function errorLine(text: string): number | undefined {
  try {
    buildPickList(text, []);
  } catch (e) {
    expect(e).toBeInstanceOf(OrderFormatError);
    return (e as OrderFormatError).line;
  }
  return undefined;
}

test("parses the example and allocates FEFO with priority first", () => {
  const text = `# export 2026-10-12 06:00
ORDER 1001
  OLIVE-500 x3
  PASTA-1KG x1
ORDER 1002 !
  OLIVE-500 x2
`;
  const stock: StockLot[] = [
    { bin: "B-01-1", sku: "OLIVE-500", qty: 2, expires: null },
    { bin: "A-02-1", sku: "OLIVE-500", qty: 2, expires: "2027-01-01" },
    { bin: "A-01-1", sku: "OLIVE-500", qty: 2, expires: "2027-01-01" },
  ];
  const snapshot = structuredClone(stock);
  const result = buildPickList(text, stock);
  expect(stock).toEqual(snapshot);
  expect(result.picks).toEqual([
    { bin: "A-01-1", sku: "OLIVE-500", qty: 2, orderId: "1002" },
    { bin: "A-02-1", sku: "OLIVE-500", qty: 2, orderId: "1001" },
    { bin: "B-01-1", sku: "OLIVE-500", qty: 1, orderId: "1001" },
  ]);
  expect(result.shortages).toEqual([{ orderId: "1001", sku: "PASTA-1KG", missing: 1 }]);
});

test("merges duplicate SKUs within an order", () => {
  const text = "ORDER A\nX x1\nY x1\nX   x2";
  const stock: StockLot[] = [{ bin: "A-01-1", sku: "X", qty: 1, expires: null }];
  expect(buildPickList(text, stock).shortages).toEqual([
    { orderId: "A", sku: "X", missing: 2 },
    { orderId: "A", sku: "Y", missing: 1 },
  ]);
});

test("serpentine walking order", () => {
  const text = "ORDER 1\nS x9";
  const bins = ["C-01-1", "A-02-1", "C-02-2", "A-01-2", "A-01-1", "C-02-1"];
  const stock = bins.map((bin) => ({ bin, sku: "S", qty: 1, expires: null }));
  expect(buildPickList(text, stock).picks.map((p) => p.bin)).toEqual([
    "A-01-1", "A-01-2", "A-02-1", "C-02-1", "C-02-2", "C-01-1",
  ]);
});

test("format errors report the first problem", () => {
  expect(errorLine("X x1\nORDER 1\nX x1")).toBe(1);
  expect(errorLine("ORDER 1\nX x1\nORDER 1\nX x1")).toBe(3);
  expect(errorLine("ORDER 1\n\nORDER 2\nX x1")).toBe(1);
  expect(errorLine("ORDER 1\nX x1\nORDER 2")).toBe(3);
  expect(errorLine("ORDER 1\nX x0")).toBe(2);
  expect(errorLine("ORDER 1\nX x03")).toBe(2);
  expect(errorLine("ORDER 1\nx x3")).toBe(2);
  expect(errorLine("ORDER 1\nX 3")).toBe(2);
  expect(errorLine("ORDER 1!\nX x1")).toBe(1);
  expect(errorLine("# c\nORDER 1   !\n  X x1  ")).toBeUndefined();
});
EOF
